window.products.push({"id":821995,"name":"Unique Personalized Wood Engraved Heart Trees and Birds Wedding Guest Book Photo Albums Scrapbook","category":"homeandappliances","retail price":47.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71v4a-tBfoL._AC_SL1500_.jpg","description":"PRODUCT: 1 Guestbook with Ring Binding which will help you add or remove extra pages. |  Includes: 80 pages (40 sheets). CUSTOMIZATION: Click on Customize Now button on your right and fill the detail carefully on the text area & complete your checkout. FIRST PAGE AND ALL PAGES Color: Along With your Text details also mention the Inside pages Color options that you would like as we offer 3 Colors i.e WHITE/ BLACK/ BEIGE (White By Default) + First Page Color from the given Options (Mention the number as per our Color chart). We need 4-6 days time to produce your book and once it is ready it will be shipped via FedEx / DHL which will deliver the parcel in 3-6 working days.","images":["https://m.media-amazon.com/images/I/71v4a-tBfoL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Darling Souvenir","source_asin":"B072F22R78","category_path":"Home & Kitchen"},"sku":"BM-821995","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B072F22R78","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B072F22R78","price_pending":true,"merchant_ready":false});
